import gurobipy as gp
from gurobipy import GRB
supplier_caps = {}
for rec in LEGACY_RECORDS:
    if rec['source'] == 'supply_capacity.csv':
        supplier = rec['values']['Unnamed: 0']
        cap = float(rec['values']['supply_capacity'])
        supplier_caps[supplier] = cap
suppliers = list(supplier_caps.keys())
customer_demands = {}
for rec in LEGACY_RECORDS:
    if rec['source'] == 'customer_demand.csv':
        customer = rec['values']['customer']
        demand = float(rec['values']['demand'])
        customer_demands[customer] = demand
customers = list(customer_demands.keys())
costs = {}
for rec in LEGACY_RECORDS:
    if rec['source'] == 'transportation_costs.csv':
        supplier = rec['values']['Unnamed: 0']
        for customer in customers:
            key = (supplier, customer)
            costs[key] = float(rec['values'][customer])
for i in suppliers:
    for j in customers:
        if (i, j) not in costs:
            raise ValueError(f'Missing cost for ({i},{j})')
m = gp.Model('transportation')
x = m.addVars(suppliers, customers, lb=0, vtype=GRB.CONTINUOUS, name='')
m.setObjective(gp.quicksum((costs[i, j] * x[i, j] for i in suppliers for j in customers)), GRB.MINIMIZE)
m.addConstrs((gp.quicksum((x[i, j] for j in customers)) <= supplier_caps[i] for i in suppliers), name='')
m.addConstrs((gp.quicksum((x[i, j] for i in suppliers)) == customer_demands[j] for j in customers), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')